extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var story_path := "res://story/main_story.json"
	if not check("file_exists", FileAccess.file_exists(story_path), "Il file res://story/main_story.json deve esistere"):
		return

	var file := FileAccess.open(story_path, FileAccess.READ)
	if not check("file_open", file != null, "Impossibile aprire il file res://story/main_story.json"):
		return

	var json_data: Variant = JSON.parse_string(file.get_as_text())
	if not check("json_valid", json_data is Dictionary, "Il file deve contenere un oggetto JSON valido"):
		return

	var chapter: Dictionary = json_data
	if not check("has_title", chapter.has("title") and chapter["title"] is String, "Il file deve avere la chiave 'title' con una stringa"):
		return

	var lines_variant: Variant = chapter.get("lines", null)
	if not check("has_lines", lines_variant is Array and not (lines_variant as Array).is_empty(), "La storia deve contenere una lista 'lines' non vuota"):
		return

	var lines: Array = lines_variant
	var has_start: bool = false
	var dialogue_count: int = 0
	var choice_count: int = 0
	var set_count: int = 0
	var condition_count: int = 0
	var declared_labels: Dictionary = {}
	var targets_to_check: Array[String] = []
	var known_speakers: Array[String] = ["Elena", "Marco", "???", ""]
	var invalid_speakers: Array[String] = []

	for entry in lines:
		if not entry is Dictionary:
			continue
		var cmd: Dictionary = entry
		var ctype: String = String(cmd.get("type", ""))

		if ctype == "label":
			var lname: String = String(cmd.get("id", cmd.get("name", "")))
			if not lname.is_empty():
				declared_labels[lname] = true
			if lname == "inizio":
				has_start = true

		if cmd.has("text") and not String(cmd.get("text", "")).strip_edges().is_empty():
			dialogue_count += 1

		if cmd.has("speaker"):
			var spk: String = String(cmd.get("speaker", ""))
			if not known_speakers.has(spk):
				invalid_speakers.append(spk)

		if ctype == "choice":
			var opts: Variant = cmd.get("options", [])
			if opts is Array and opts.size() >= 2:
				choice_count += 1
				for opt_entry in opts:
					if opt_entry is Dictionary:
						var opt: Dictionary = opt_entry
						var target: String = String(opt.get("target", ""))
						if not target.is_empty():
							targets_to_check.append(target)
						if opt.has("condition"):
							condition_count += 1

		if ctype == "jump":
			var target: String = String(cmd.get("target", ""))
			if not target.is_empty():
				targets_to_check.append(target)

		if ctype == "set":
			if cmd.has("variable") and cmd.has("value"):
				set_count += 1

		if cmd.has("condition"):
			condition_count += 1

	check("label_inizio", has_start, "La storia deve definire un'etichetta iniziale con id 'inizio'")
	check("min_dialogues", dialogue_count >= 6, "Devono essere presenti almeno 6 battute di dialogo (trovate %d)" % dialogue_count)
	check("valid_speakers", invalid_speakers.is_empty(), "I personaggi devono essere validi (Elena, Marco o '')")
	check("has_choice", choice_count >= 1, "Deve essere presente almeno un comando 'choice' con almeno 2 opzioni")
	check("has_set", set_count >= 1, "Deve essere presente almeno un comando 'set' per memorizzare una variabile")
	check("has_condition", condition_count >= 1, "Deve essere presente almeno una battuta o opzione con 'condition'")

	var missing_targets: Array[String] = []
	for target in targets_to_check:
		if not declared_labels.has(target):
			missing_targets.append(target)
	check("targets_exist", missing_targets.is_empty(), "Tutti i salti e le scelte devono puntare a etichette esistenti (mancanti: %s)" % str(missing_targets))

	var validator := StoryValidator.new()
	var val_errors: Array[String] = validator.validate_chapter(story_path)
	check("validator_clean", val_errors.is_empty(), "StoryValidator non deve rilevare errori nel file: %s" % str(val_errors))

