class_name TestShake
extends RefCounted


func test_shake_command(interpreter: StoryInterpreter) -> bool:
	if not interpreter or not interpreter.character_stage:
		return false

	var initial_pos: Vector2 = interpreter.character_stage.position
	var start_time: int = Time.get_ticks_msec()

	await interpreter.execute_command({
		"type": "shake",
		"duration": 0.2,
		"strength": 10.0
	})

	var elapsed_sec: float = float(Time.get_ticks_msec() - start_time) / 1000.0

	if elapsed_sec < 0.15:
		return false

	if interpreter.character_stage.position != initial_pos:
		return false

	return true

