extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var story_path := "res://story/main_story.json"
	if not check("file_main_story", FileAccess.file_exists(story_path), "Il file principale della storia res://story/main_story.json deve esistere"):
		return

	var validator_source := source_of("res://story/story_validator.gd")
	if not check("validator_presente", not validator_source.is_empty(), "Lo script res://story/story_validator.gd deve essere presente e valido"):
		return

	check("validator_has_method", validator_source.contains("func validate_chapter"), "Lo script StoryValidator deve contenere la funzione validate_chapter")

	var files_cache: Dictionary = {}
	var all_labels_by_file: Dictionary = {}
	var visited_labels_by_file: Dictionary = {}
	var reached_endings: Dictionary = {}
	var total_words: int = 0
	var total_chars: int = 0
	var choices_count: int = 0

	var queue: Array[Dictionary] = [{"file": story_path, "idx": 0}]
	var visited_states: Dictionary = {}

	while not queue.is_empty():
		var state: Dictionary = queue.pop_front()
		var fpath: String = state["file"]
		var idx: int = state["idx"]
		var state_key: String = "%s:%d" % [fpath, idx]
		if visited_states.has(state_key):
			continue
		visited_states[state_key] = true

		if not files_cache.has(fpath):
			var data: Variant = _load_json_file(fpath)
			if not data is Dictionary:
				continue
			files_cache[fpath] = data
			var labels_dict: Dictionary = {}
			var flines: Array = data.get("lines", [])
			for i in range(flines.size()):
				var item: Variant = flines[i]
				if item is Dictionary and item.get("type", "") == "label":
					var lname: String = String(item.get("id", item.get("name", "")))
					if not lname.is_empty():
						labels_dict[lname] = i
			all_labels_by_file[fpath] = labels_dict
			visited_labels_by_file[fpath] = {}

		var cdata: Dictionary = files_cache[fpath]
		var clines: Array = cdata.get("lines", [])

		if idx >= clines.size():
			reached_endings[state_key] = true
			continue

		var cmd_raw: Variant = clines[idx]
		if not cmd_raw is Dictionary:
			queue.append({"file": fpath, "idx": idx + 1})
			continue

		var cmd: Dictionary = cmd_raw
		var ctype: String = String(cmd.get("type", ""))

		if cmd.has("text"):
			var txt: String = String(cmd.get("text", ""))
			total_chars += txt.length()
			var words := txt.split(" ", false)
			total_words += words.size()

		if ctype == "label":
			var lname: String = String(cmd.get("id", cmd.get("name", "")))
			if not lname.is_empty():
				visited_labels_by_file[fpath][lname] = true
			queue.append({"file": fpath, "idx": idx + 1})
		elif ctype == "jump":
			var target: String = String(cmd.get("target", ""))
			var file_labels: Dictionary = all_labels_by_file[fpath]
			if file_labels.has(target):
				queue.append({"file": fpath, "idx": file_labels[target]})
		elif ctype == "jump_chapter":
			var target_file: String = String(cmd.get("target_file", ""))
			var target_label: String = String(cmd.get("target_label", ""))
			if FileAccess.file_exists(target_file):
				if not files_cache.has(target_file):
					var target_data: Variant = _load_json_file(target_file)
					if target_data is Dictionary:
						files_cache[target_file] = target_data
						var tlabels: Dictionary = {}
						var tlines: Array = target_data.get("lines", [])
						for i in range(tlines.size()):
							var item: Variant = tlines[i]
							if item is Dictionary and item.get("type", "") == "label":
								var lname: String = String(item.get("id", item.get("name", "")))
								if not lname.is_empty():
									tlabels[lname] = i
						all_labels_by_file[target_file] = tlabels
						visited_labels_by_file[target_file] = {}
				var target_labels: Dictionary = all_labels_by_file.get(target_file, {})
				var target_idx: int = target_labels.get(target_label, 0)
				queue.append({"file": target_file, "idx": target_idx})
		elif ctype == "choice":
			choices_count += 1
			var options: Variant = cmd.get("options", [])
			if options is Array:
				for opt_raw in options:
					if opt_raw is Dictionary:
						var opt: Dictionary = opt_raw
						var target: String = String(opt.get("target", ""))
						var file_labels: Dictionary = all_labels_by_file[fpath]
						if file_labels.has(target):
							queue.append({"file": fpath, "idx": file_labels[target]})
		elif ctype == "ending" or ctype == "end" or (ctype == "unlock" and cmd.get("kind") == "ending"):
			var eid: String = String(cmd.get("id", state_key))
			reached_endings[eid] = true
		else:
			queue.append({"file": fpath, "idx": idx + 1})

	check("bivi_presenti", choices_count > 0, "La storia deve contenere scelte ramificate (trovate: %d)" % choices_count)
	check("almeno_due_finali", reached_endings.size() >= 2, "La storia deve avere almeno due finali diversi raggiungibili (trovati: %d)" % reached_endings.size())

	var unreached: Array[String] = []
	for f in all_labels_by_file.keys():
		var all_f_labels: Dictionary = all_labels_by_file[f]
		var vis_f_labels: Dictionary = visited_labels_by_file.get(f, {})
		for l in all_f_labels.keys():
			if not vis_f_labels.has(l):
				unreached.append("%s:%s" % [f.get_file(), l])

	check("nessun_punto_irraggiungibile", unreached.is_empty(), "Nessun punto della storia deve essere irraggiungibile; etichette non raggiunte: %s" % str(unreached))

	var durata_ok: bool = total_words >= 1500 or total_chars >= 8000
	check("durata_stimata_dieci_minuti", durata_ok, "La narrazione deve superare i 10 minuti di lettura stimata (trovate %d parole e %d caratteri, richiesti almeno 1500 parole o 8000 caratteri)" % [total_words, total_chars])


func _load_json_file(path: String) -> Variant:
	if not FileAccess.file_exists(path):
		return null
	var file := FileAccess.open(path, FileAccess.READ)
	if not file:
		return null
	return JSON.parse_string(file.get_as_text())

